 [TestMethod]public Task RawSharedStackMaskUndoCopySaveReopenAndTiffExportStayRaw()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Path.Combine(Path.GetTempPath(),"r53-raw-local-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   var path=Path.Combine(root,"synthetic.cr3");File.WriteAllBytes(path,[1,2,3]);var decoder=new Linear();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(root),rawDecoder:new Legacy(),professionalRawDecoder:decoder);await vm.LoadTargetAsync(path);await vm.CreateProfessionalRawCommand.ExecuteAsync(null);var target=vm.ActiveTarget!;var id=target.ActiveEditVersionId;var decode=decoder.Count;Assert.IsTrue(vm.RawLocalEditing);Assert.IsTrue(vm.DarkroomAdjustmentEnabled);
   var exposure=ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure");vm.Editor.SetToolParameter(exposure,.7);vm.Editor.SelectedLayerOpacity=.55;vm.Editor.AddMaskStroke(new([new(.2,.3),new(.7,.6)],.15,.5,.7,1));await vm.RawLocalPreviewWork;Assert.IsNotNull(target.RawDefinition!.LocalEdits);Assert.AreEqual(4,target.RawDefinition.ProcessingVersion);Assert.AreEqual(id,target.ActiveEditVersionId);Assert.AreEqual(decode,decoder.Count);var beforeGeometry=JsonSerializer.Serialize(target.RawDefinition);vm.SetRawOutputGeometry(new(.1,.1,.8,.8,1,true));await vm.RawLocalPreviewWork;Assert.IsNotNull(target.RawDefinition.Geometry);await vm.PhotoGradeUndoCommand.ExecuteAsync(null);await vm.RawLocalPreviewWork;Assert.AreEqual(beforeGeometry,JsonSerializer.Serialize(target.RawDefinition));var frozen=JsonSerializer.Serialize(target.RawDefinition);await vm.RawLocalPreviewWork;var pixels=Pixels(vm.Editor.MatchedImage!);using(var oracle=ProfessionalRawPipeline.RenderPreview(target.LinearRawMaster!,target.RawDefinition,1600))CollectionAssert.AreEqual(pixels,Pixels(RawDisplayBitmapAdapter.ToBitmap(oracle.ToVisualRgb24())),"RAW first preview must match frozen oracle");
