   await vm.CreateR53VariantAsync(false);vm.Editor.InvertLocalMask();await vm.RawLocalPreviewWork;Assert.AreNotEqual(frozen,JsonSerializer.Serialize(target.RawDefinition));await vm.SwitchEditVersionAsync(id!.Value);Assert.AreEqual(frozen,JsonSerializer.Serialize(target.RawDefinition));CollectionAssert.AreEqual(pixels,Pixels(vm.Editor.MatchedImage!),"RAW variant switch pixels");vm.Editor.SelectedNodeLocked=true;vm.Editor.ClearLocalMask();Assert.AreEqual(frozen.Replace("\"UserLocked\":false","\"UserLocked\":true"),JsonSerializer.Serialize(target.RawDefinition));vm.Editor.SelectedNodeLocked=false;
   var project=Path.Combine(root,"raw.ptstudio.json");await vm.SaveSessionAsync(project);using var reopened=new ReferenceColorWorkspaceViewModel(new Dialogs(root),rawDecoder:new Legacy(),professionalRawDecoder:new Linear());await reopened.LoadSessionAsync(project);Assert.IsTrue(reopened.Editor.RawLocalEditing);Assert.IsNotNull(reopened.Editor.SelectedAdjustmentNode?.LocalMask);CollectionAssert.AreEqual(pixels,Pixels(reopened.Editor.MatchedImage!),"RAW reopened pixels");reopened.Editor.SelectedLayerOpacity=.35;await reopened.RawLocalPreviewWork;Assert.AreEqual(.35,reopened.ActiveTarget!.RawDefinition!.LocalEdits!.Stack.Nodes[0].Opacity);reopened.ActiveTarget.IsSelected=true;await reopened.ExportSelectedCommand.ExecuteAsync(null);Assert.AreEqual(ReferenceExportStatus.Succeeded,reopened.ActiveTarget.ExportStatus,reopened.ActiveTarget.Error);var exported=reopened.ActiveTarget.OutputPath!;Assert.IsTrue(exported.EndsWith(".tif"));var inspection=ProfessionalRawExport.Inspect(exported,reopened.ActiveTarget.LinearRawMaster!,reopened.ActiveTarget.RawDefinition,StudioExportFormat.Tiff);Assert.AreEqual(0,inspection.MaximumError);
